def solve(data):
    capacity = data["capacity"]
    ops = data["ops"]

    if capacity == 0:
        return []

    cache = {}
    recent_used = set()
    result = []

    for op in ops:
        if op[0] == "put":
            key, value = op[1:]

            if len(cache) < capacity:
                cache[key] = value
                recent_used.add(key)
            else:
                # Remove the least recently used item from the cache
                min_key = min(recent_used)
                del cache[min_key]
                recent_used.remove(min_key)

                # Add the new item to the cache
                cache[key] = value
                recent_used.add(key)

        elif op[0] == "get":
            key = op[1]
            if key in cache:
                result.append(cache[key])
                recent_used.add(key)
            else:
                result.append(-1)

    return result

