def solve(data):
    capacity = data['capacity']
    ops = data['ops']

    if not ops:
        return []

    cache = OrderedDict()
    result = []

    for op_type, key, value in ops:
        if op_type == 'put':
            if len(cache) < capacity:
                cache[key] = value
            else:
                oldest_key = next(iter(cache))
                del cache[oldest_key]
                cache[key] = value
        elif op_type == 'get':
            if key in cache:
                result.append(cache[key])
                # Update most recently used by moving the key to the end of the OrderedDict
                cache.move_to_end(key)
            else:
                result.append(-1)

    return result

