    ops = data['ops']

    # Initialize cache with OrderedDict for LRU behavior
    cache = OrderedDict()

    result = []

    for op, key, value in ops:
        if op == 'put':
            # If key already exists, update its value and move to end
            if key in cache:
                del cache[key]
            cache[key] = value
            # Ensure cache size does not exceed capacity
            while len(cache) > capacity:
                cache.popitem(last=False)
        elif op == 'get':
            # Get value from cache
            if key in cache:
                result.append(cache[key])
                # Move the accessed item to the end
                cache.move_to_end(key, last=True)
            else:
                result.append(-1)

    return result

