def solve(data):
    capacity = data['capacity']
    ops = data['ops']

    # Initialize the cache with a list of lists where each sublist represents [value, timestamp]
    cache = [[] for _ in range(capacity)]

    # Dictionary to keep track of the last use time of each key
    last_used_time = {}

    result = []

    for op_type, key, value in ops:
        if op_type == 'put':
            if len(cache[key]) >= capacity:
                # Remove the least recently used item if the cache is full
                del cache[last_used_time[min(last_used_time.values())]][1]
                del last_used_time[min(last_used_time.values())]

            # Update the cache with the new value and set the last use time
            cache[key].append([value, max(last_used_time.get(key, 0), len(cache[key]))])
            last_used_time[key] = max(last_used_time.get(key, 0), len(cache[key]))

        elif op_type == 'get':
            if key in last_used_time:
                # Mark the key as recently used
                last_used_time[key] = len(cache[key])
            else:
                return [-1]

            # Get the value associated with the key from the cache
            result.append(cache[key][0])

    return result

