from collections import OrderedDict

def solve(data):
    capacity = data['capacity']
    ops = data['ops']

    if capacity == 0:
        return []

    cache = OrderedDict()
    recent_ops = []

    for op_type, key, value in ops:
        if op_type == 'put':
            if key in cache:
                recent_ops.remove((key, cache[key]))
            cache[key] = value
            recent_ops.append((key, value))
