        return int(tokens[0])

    # Stack to store operands
    stack = []

    for token in tokens:
        try:
            # Check if the token is an operand
            num = int(token)
            stack.append(num)
        except ValueError:
            # Token is an operator
            if not stack or len(stack) < 2:
                raise ValueError("Invalid input")

            right = stack.pop()
            left = stack.pop()

            if token == '+':
                stack.append(left + right)
