            elif token == '*':
                stack.append(left * right)
            elif token == '/':
                if right == 0:
                    raise ValueError("Division by zero")
                stack.append(left // right)

    # Final result should be on the top of the stack
    if len(stack) != 1:
        raise ValueError("Invalid input")

    return stack[0]

