class Solution {
    public static List<Integer> solve(Map<String, Object> data) {
        List<Integer> nums = (List<Integer>) data.get("nums");
        List<List<Object>> operations = (List<List<Object>>) data.get("operations");
        List<Integer> result = new ArrayList<>();

        int[] prefixSum = new int[nums.size()];
        for (int i = 0; i < nums.size(); i++) {
            if (i == 0) {
                prefixSum[i] = nums.get(i);
            } else {
                prefixSum[i] = prefixSum[i - 1] + nums.get(i);
            }
        }

        for (List<Object> operation : operations) {
            String opType = (String) operation.get(0);
            int l = ((Number) operation.get(1)).intValue();
            int r = ((Number) operation.get(2)).intValue();

            if (opType.equals("add")) {
                prefixSum[r] += ((Number) operation.get(3)).intValue();
                prefixSum[l - 1] -= ((Number) operation.get(3)).intValue();
            } else if (opType.equals("sum")) {
                result.add(prefixSum[r] - (l > 0 ? prefixSum[l - 1] : 0));
            }
        }

        return result;
    }
}

