    public static Object solve(Map<String,Object> data) {
        List<Integer> nums = new ArrayList<>(((List<?>) data.get("nums")).stream().mapToInt(Number::intValue).toArray());
        List<Integer> operations = ((List<?>) data.get("operations")).stream()
            .map(o -> {
                String op = (String) o.get(0);
                int l = ((Number) o.get(1)).intValue();
                int r = ((Number) o.get(2)).intValue();
                int v = ((Number) o.get(3)).intValue();
                if ("add".equals(op)) {
                    nums.set(l, nums.get(l) + v);
                }
                return nums.subList(l, r + 1).stream().mapToInt(Integer::intValue).sum();
            }).collect(Collectors.toList());

        return operations;
    }

    public static void main(String[] args) {
        // Test cases
        System.out.println(solve(Map.of("nums", Arrays.asList(1, 2, 3), "operations", Arrays.asList(
            Arrays.asList("sum", 0, 2),
            Arrays.asList("add", 0, 1, 4),
            Arrays.asList("sum", 1, 2)
        )))); // Output: [6, 9]

        System.out.println(solve(Map.of("nums", Arrays.asList(0), "operations", Arrays.asList(
            Arrays.asList("add", 0, 0, -1),
            Arrays.asList("sum", 0, 0)
        )))); // Output: [-1]

        System.out.println(solve(Map.of("nums", Arrays.asList(5, 5), "operations", Arrays.asList(
            Arrays.asList("sum", 1, 1)
        )))); // Output: [5]

        System.out.println(solve(Map.of("nums", Arrays.asList(3, -2, 10), "operations", Collections.emptyList()))); // Output: []
    }
}

