class Solution {
    public static List<Integer> solve(Map<String,Object> data) {
        int[] nums = ((List<Integer>) data.get("nums")).stream().mapToInt(Integer::intValue).toArray();
        List<Integer> ops = new ArrayList<>();
        List<Integer> res = new ArrayList<>();

        for (Object o : data.get("operations")) {
            if (o instanceof String[]) {
                String[] op = (String[]) o;
                switch (op[0]) {
                    case "add":
                        nums[op[1]] += Integer.parseInt(op[3]);
                        break;
                    case "sum":
                        res.add(Arrays.stream(nums).skip(op[1]).limit(op[2] + 1).sum());
                        break;
                }
            }
        }

        return res;
    }
}

