    public static Object solve(Map<String,Object> data) {
        List<Integer> nums = (List<Integer>) data.get("nums");
        List<List<Object>> operations = (List<List<Object>>) data.get("operations");

        int n = nums.size();
        List<Integer> prefixSum = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (i == 0) {
                prefixSum.add(nums.get(i));
            } else {
                prefixSum.add(prefixSum.get(i - 1) + nums.get(i));
            }
        }

        List<Integer> result = new ArrayList<>();
        for (List<Object> operation : operations) {
            String opType = (String) operation.get(0);
            int l = ((Number) operation.get(1)).intValue();
            int r = ((Number) operation.get(2)).intValue();

            if ("add".equals(opType)) {
                int v = ((Number) operation.get(3)).intValue();
                prefixSum.set(l, prefixSum.get(l) + v);
                prefixSum.set(r + 1, prefixSum.get(r + 1) - v);
            } else {
                int sum = 0;
                for (int i = l; i <= r; i++) {
                    sum += prefixSum.get(i);
                }
                result.add(sum);
            }
        }

        return result;
    }
}

