public final class Solution {
    public static Object solve(Map<String,Object> data) {
        List<Integer> nums = (List<Integer>) data.get("nums");
        List<List<Object>> operations = (List<List<Object>>) data.get("operations");

        // Edge case: empty or minimal inputs
        if (nums == null || nums.isEmpty() || operations == null || operations.isEmpty()) {
            return new ArrayList<>();
        }

        int n = nums.size();
        List<Integer> prefixSum = new ArrayList<>(Collections.nCopies(n + 1, 0));

        // Calculate prefix sums
        for (int i = 0; i < n; i++) {
            prefixSum.set(i + 1, prefixSum.get(i) + nums.get(i));
        }

        List<Integer> result = new ArrayList<>();

        // Process operations
        for (List<Object> operation : operations) {
            String opType = (String) operation.get(0);
            int l = ((Integer) operation.get(1)).intValue();
            int r = ((Integer) operation.get(2)).intValue();

            if (opType.equals("add")) {
                // Add value to the specified range
                prefixSum.set(r + 1, prefixSum.get(r + 1) - nums.get(l) + ((Integer) operation.get(3)).intValue());
            } else if (opType.equals("sum")) {
                // Append the sum of the specified range to the result
                result.add(prefixSum.get(r + 1) - prefixSum.get(l));
            }
        }

        return result;
    }
}

