public final class Solution {
    public static Object solve(Map<String,Object> data) {
        List<int[]> edges = (List<int[]>) data.get("edges");
        int left = ((Number) data.get("left")).intValue();
        int right = ((Number) data.get("right")).intValue();

        // Edge cases: empty input, minimal inputs, boundary values, duplicates, large inputs
        if (edges == null || edges.isEmpty()) return 0;
        if (left < 0 || left > right || right < 0 || right > 12) throw new IllegalArgumentException("Invalid input");

        // Brute-force approach: try all possible subsets of edges
        int maxDisjointPairs = 0;
        for (int i = 1; i <= edges.size(); i++) {
            for (Set<int[]> subset : Combinations.combinations(edges, i)) {
                boolean valid = true;
                for (int[] pair : subset) {
                    if (pair[0] >= left && pair[0] <= right && pair[1] >= left && pair[1] <= right) {
                        valid = false;
                        break;
                    }
                }
                if (valid) maxDisjointPairs = Math.max(maxDisjointPairs, subset.size());
            }
        }

        return maxDisjointPairs;
    }

    private static class Combinations {
        public static <T> Set<List<T>> combinations(List<T> list, int k) {
            Set<List<T>> result = new HashSet<>();
            if (k == 0) {
                result.add(new ArrayList<>());
                return result;
            }
            for (int i = 0; i <= list.size() - k; i++) {
                List<T> subList = new ArrayList<>(list.subList(i, i + k));
                Set<List<T>> subCombinations = combinations(list.subList(i + 1, list.size()), k - 1);
                for (List<T> combination : subCombinations) {
                    List<T> newCombination = new ArrayList<>(subList);
                    newCombination.addAll(combination);
                    result.add(newCombination);
                }
            }
            return result;
        }
    }
}

