            if (u >= left && u <= right && v >= left && v <= right) {
                count.put(u, count.getOrDefault(u, 0) + 1);
                count.put(v, count.getOrDefault(v, 0) + 1);
            }
        }

        for (int key : count.keySet()) {
            maxDisjointPairs += count.get(key) / 2;
        }

        return maxDisjointPairs;
    }
}

