class Solution {
    public static int solve(Map<String, Object> data) {
        List<List<Integer>> edges = (List<List<Integer>>) data.get("edges");
        int left = (int) data.get("left");
        int right = (int) data.get("right");

        if (edges.isEmpty() || left == right) {
            return 0;
        }

        int maxPairs = 0;

        // Sort edges by their start point
        Collections.sort(edges, Comparator.comparingInt(edge -> edge.get(0)));

        for (int i = 0; i < edges.size(); i++) {
            int u = edges.get(i).get(0);
            int v = edges.get(i).get(1);

            // Check if there is an available range from the current u to the next v
            int availableRangeStart = Math.max(u, left);
            int availableRangeEnd = Math.min(v, right);

            if (availableRangeStart <= availableRangeEnd) {
                maxPairs++;
            }
        }

        return maxPairs;
    }

    public static void main(String[] args) {
        Map<String, Object> testCases = new HashMap<>();
        testCases.put("edges", Arrays.asList(Arrays.asList(0, 0), Arrays.asList(1, 1)));
        testCases.put("left", 2);
        testCases.put("right", 2);
