        int L = ((Number)data.get("left")).intValue();
        int R = ((Number)data.get("right")).intValue();
        List<List<Integer>> edges = (List<List<Integer>>)data.get("edges");

        Map<Integer, Integer> leftToRightCount = new HashMap<>();
        Map<Integer, Integer> rightToLeftCount = new HashMap<>();

        for (List<Integer> edge : edges) {
            int u = edge.get(0);
            int v = edge.get(1);

            if (u <= v) {
                leftToRightCount.merge(u, 1, Integer::sum);
                rightToLeftCount.merge(v + 1, 1, Integer::sum);
            } else {
                leftToRightCount.merge(v, 1, Integer::sum);
                rightToLeftCount.merge(u + 1, 1, Integer::sum);
            }
        }

        int maxDisjointPairs = 0;
        int currentLeftCount = 0;
        int currentRightCount = 0;

        for (int i = 0; i <= R; i++) {
            currentLeftCount += leftToRightCount.getOrDefault(i, 0);
            currentRightCount += rightToLeftCount.getOrDefault(i, 0);

            maxDisjointPairs = Math.max(maxDisjointPairs, currentLeftCount);
        }

        return maxDisjointPairs;
    }
}

