        Map<Integer, Integer> endpointCount = new HashMap<>();
        for (int[] edge : edges) {
            endpointCount.put(edge[0], endpointCount.getOrDefault(edge[0], 0) + 1);
            endpointCount.put(edge[1], endpointCount.getOrDefault(edge[1], 0) + 1);
