            int v = edge[1];

            // If the endpoints of the current edge form a new segment
            if (endpointCount.get(u) > 1 && endpointCount.get(v) > 1) {
                currentSegment++;
                maxDisjointSegments = Math.max(maxDisjointSegments, currentSegment);
            } else {
                // Otherwise, reset the current segment
                currentSegment = 0;
            }
        }

        return maxDisjointSegments;
    }
